fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let round: i32 = host::display::state_get(0);
    let tx: i32 = hash(round * 2 + 1) % (w - 40);
    let ty: i32 = 30 + hash(round * 2 + 2) % (h - 70);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let mut timer: i32 = host::display::state_get(2) + 1;
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if px >= tx && px < tx + 40 && py >= ty && py < ty + 40 {
            host::display::state_set(3, host::display::state_get(3) + 1);
            host::display::state_set(0, round + 1);
            timer = 0;
        }
    }
    if timer > 120 {
        host::display::state_set(0, round + 1);
        timer = 0;
    }
    host::display::state_set(1, down);
    host::display::state_set(2, timer);
    host::display::clear(0x101010);
    host::display::fill_rect(tx, ty, 40, 40, 0xff3060);
    host::display::draw_string(8, 8, "WHACK", 0x808080, 1);
    host::display::draw_number(60, 8, host::display::state_get(3), 0xffffff, 2);
    host::display::present();
}
